/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Exports the contents of a grid (using the selected order and filters) to an Excel file. LoadWWPContext.Call(&WWPContext)
Do 'OpenDocument'
&CellRow = 1 &FirstColumn = 1
Do 'LoadGridState'
Do 'WriteFilters'
Do 'WriteColumnTitles'
Do 'WriteData'
Do 'CloseDocument'
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
Sub 'OpenDocument'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&Random = Random() * 10000 &Filename = WWP_GetDefaultExportPath() + !"trnscardapiopratoWWExport-" + &Random.ToString().Trim() + !".xlsx"
&ExcelDocument.Open(&Filename) Do 'CheckStatus' &ExcelDocument.Clear()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'CARPRATOTURNONOME' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &carPratoTurnoNome1.FromString(&GridStateDynamicFilter.Value) If not &carPratoTurnoNome1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Turno Nome", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Turno Nome", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&carPratoTurnoNome1) EndIf Case &DynamicFiltersSelector1 = !'CARPRATODATA' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &carPratoData1.FromString(&GridStateDynamicFilter.Value) &carPratoData_To1.FromString(&GridStateDynamicFilter.ValueTo) If not &carPratoData1.IsEmpty() OR not &carPratoData_To1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Data", "WWP_FilterRange") &ExcelDocument.Cells(&CellRow, &FirstColumn + 2).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 2).Color = 3 &ExcelDocument.Cells(&CellRow, &FirstColumn + 2).Text = " - " EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Date = &carPratoData1 &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Date = &carPratoData_To1 EndIf Case &DynamicFiltersSelector1 = !'CARPRATOREFEICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &carPratoRefeicao1.FromString(&GridStateDynamicFilter.Value) If not &carPratoRefeicao1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "do Prato)", "=") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &carPratoRefeicao1 EndIf Case &DynamicFiltersSelector1 = !'CARPRATOTURNO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &carPratoTurno1.FromString(&GridStateDynamicFilter.Value) If not &carPratoTurno1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Tipo de Refeição", "=") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &carPratoTurno1 EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'CARPRATOTURNONOME' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &carPratoTurnoNome2.FromString(&GridStateDynamicFilter.Value) If not &carPratoTurnoNome2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Turno Nome", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Turno Nome", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&carPratoTurnoNome2) EndIf Case &DynamicFiltersSelector2 = !'CARPRATODATA' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &carPratoData2.FromString(&GridStateDynamicFilter.Value) &carPratoData_To2.FromString(&GridStateDynamicFilter.ValueTo) If not &carPratoData2.IsEmpty() OR not &carPratoData_To2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Data", "WWP_FilterRange") &ExcelDocument.Cells(&CellRow, &FirstColumn + 2).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 2).Color = 3 &ExcelDocument.Cells(&CellRow, &FirstColumn + 2).Text = " - " EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Date = &carPratoData2 &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Date = &carPratoData_To2 EndIf Case &DynamicFiltersSelector2 = !'CARPRATOREFEICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &carPratoRefeicao2.FromString(&GridStateDynamicFilter.Value) If not &carPratoRefeicao2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "do Prato)", "=") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &carPratoRefeicao2 EndIf Case &DynamicFiltersSelector2 = !'CARPRATOTURNO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &carPratoTurno2.FromString(&GridStateDynamicFilter.Value) If not &carPratoTurno2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Tipo de Refeição", "=") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &carPratoTurno2 EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'CARPRATOTURNONOME' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &carPratoTurnoNome3.FromString(&GridStateDynamicFilter.Value) If not &carPratoTurnoNome3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Turno Nome", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Turno Nome", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&carPratoTurnoNome3) EndIf Case &DynamicFiltersSelector3 = !'CARPRATODATA' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &carPratoData3.FromString(&GridStateDynamicFilter.Value) &carPratoData_To3.FromString(&GridStateDynamicFilter.ValueTo) If not &carPratoData3.IsEmpty() OR not &carPratoData_To3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Data", "WWP_FilterRange") &ExcelDocument.Cells(&CellRow, &FirstColumn + 2).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 2).Color = 3 &ExcelDocument.Cells(&CellRow, &FirstColumn + 2).Text = " - " EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Date = &carPratoData3 &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Date = &carPratoData_To3 EndIf Case &DynamicFiltersSelector3 = !'CARPRATOREFEICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &carPratoRefeicao3.FromString(&GridStateDynamicFilter.Value) If not &carPratoRefeicao3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "do Prato)", "=") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &carPratoRefeicao3 EndIf Case &DynamicFiltersSelector3 = !'CARPRATOTURNO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &carPratoTurno3.FromString(&GridStateDynamicFilter.Value) If not &carPratoTurno3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Tipo de Refeição", "=") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &carPratoTurno3 EndIf EndCase EndIf EndIf EndIf If not (&TFcarPratoData.IsEmpty() AND &TFcarPratoData_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Data") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Date = &TFcarPratoData WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Date = &TFcarPratoData_To EndIf If not (&TFcarPratoTurnoHorario.IsEmpty() AND &TFcarPratoTurnoHorario_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Horário") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = &TFcarPratoTurnoHorario.ToFormattedString() WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Text = &TFcarPratoTurnoHorario_To.ToFormattedString() EndIf If not (&TFcarPratoTurno_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Turno") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = &TFcarPratoTurno_SelDsc
Else If not (&TFcarPratoTurno.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Turno") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFcarPratoTurno) EndIf EndIf If not (&TFcarPratoRefeicao_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "do Prato)") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = &TFcarPratoRefeicao_SelDsc
Else If not (&TFcarPratoRefeicao.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "do Prato)") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFcarPratoRefeicao) EndIf EndIf &CellRow += 2
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&VisibleColumnCount = 0 If &Session.Get(!'trnscardapiopratoWWColumnsSelector') <> '' &ColumnsSelectorXML = &Session.Get(!'trnscardapiopratoWWColumnsSelector') &ColumnsSelector.FromXml(&ColumnsSelectorXML) Else Do 'InitializeColumnsSelector' EndIf
&ColumnsSelector.Columns.Sort(!'Order') For &ColumnsSelector_Column in &ColumnsSelector.Columns If &ColumnsSelector_Column.IsVisible = True &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = GetMessageText(iif(&ColumnsSelector_Column.DisplayName.IsEmpty(), &ColumnsSelector_Column.ColumnName, &ColumnsSelector_Column.DisplayName)) &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Color = 11 &VisibleColumnCount += 1 EndIf EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnscardapioprato order carPratoData carPratoHorario when &OrderedBy = 1 order prefCodigo carDapCodigo carPratoData when &OrderedBy = 2 AND &OrderedDsc = False order (prefCodigo) (carDapCodigo) (carPratoData) when &OrderedBy = 2 AND &OrderedDsc = True order prefCodigo carDapCodigo carPratoData carPratoTurnoHorario when &OrderedBy = 3 AND &OrderedDsc = False order (prefCodigo) (carDapCodigo) (carPratoData) (carPratoTurnoHorario) when &OrderedBy = 3 AND &OrderedDsc = True order prefCodigo carDapCodigo carPratoData carPratoTurno when &OrderedBy = 4 AND &OrderedDsc = False order (prefCodigo) (carDapCodigo) (carPratoData) (carPratoTurno) when &OrderedBy = 4 AND &OrderedDsc = True order prefCodigo carDapCodigo carPratoData carPratoRefeicao when &OrderedBy = 5 AND &OrderedDsc = False order (prefCodigo) (carDapCodigo) (carPratoData) (carPratoRefeicao) when &OrderedBy = 5 AND &OrderedDsc = True
using trnscardapiopratoWWDS(&prefCodigo, &carDapCodigo, &DynamicFiltersSelector1, &DynamicFiltersOperator1, &carPratoTurnoNome1, &carPratoData1 , &carPratoData_To1, &carPratoRefeicao1, &carPratoTurno1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2 , &carPratoTurnoNome2, &carPratoData2, &carPratoData_To2, &carPratoRefeicao2, &carPratoTurno2, &DynamicFiltersEnabled3 , &DynamicFiltersSelector3, &DynamicFiltersOperator3, &carPratoTurnoNome3, &carPratoData3, &carPratoData_To3, &carPratoRefeicao3 , &carPratoTurno3, &TFcarPratoData, &TFcarPratoData_To, &TFcarPratoTurnoHorario, &TFcarPratoTurnoHorario_To, &TFcarPratoTurno , &TFcarPratoTurno_Sel, &TFcarPratoRefeicao, &TFcarPratoRefeicao_Sel) Where prefCodigo = &prefCodigo
// Write cell values &CellRow += 1
Do 'BeforeWriteLine' &VisibleColumnCount = 0 For &ColumnsSelector_Column in &ColumnsSelector.Columns If &ColumnsSelector_Column.IsVisible = True Do Case Case &ColumnsSelector_Column.ColumnName = !'carPratoData' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Date = carPratoData Case &ColumnsSelector_Column.ColumnName = !'carPratoTurnoHorario' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = carPratoTurnoHorario.ToFormattedString() Case &ColumnsSelector_Column.ColumnName = !'carPratoTurno' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(refTipDescricao) Case &ColumnsSelector_Column.ColumnName = !'carPratoRefeicao' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(pratoDscricao50) EndCase &VisibleColumnCount += 1 EndIf EndFor
Do 'AfterWriteLine'
Endfor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CloseDocument'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ExcelDocument.Save() Do 'CheckStatus' &ExcelDocument.Close() &Session.Set(!'WWPExportFilePath', &Filename) &Session.Set(!'WWPExportFileName', !"trnscardapiopratoWWExport.xlsx") &Filename = WWP_DownloadReport.Link()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CheckStatus'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If (&ExcelDocument.ErrCode <> 0) &Filename = "" &ErrorMessage = &ExcelDocument.ErrDescription &ExcelDocument.Close() Return EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'InitializeColumnsSelector'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ColumnsSelector = new WWPColumnsSelector() WWP_ColumnsSelector_Add(&ColumnsSelector, !"carPratoData", '', !'Data', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"carPratoTurnoHorario", '', !'Horário', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"carPratoTurno", '', !'Turno', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"carPratoRefeicao", '', !'do Prato)', True, '')
&UserCustomValue = LoadColumnsSelectorState.Udp(!'trnscardapiopratoWWColumnsSelector') If not(&UserCustomValue.IsEmpty()) &ColumnsSelectorAux.FromXml(&UserCustomValue) WWP_ColumnSelector_UpdateColumns(&ColumnsSelectorAux, &ColumnsSelector) EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnscardapiopratoWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnscardapiopratoWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnscardapiopratoWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFCARPRATODATA" &TFcarPratoData.FromString(&GridStateFilterValue.Value) &TFcarPratoData_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFCARPRATOTURNOHORARIO" &TFcarPratoTurnoHorario.FromString(&GridStateFilterValue.Value) &TFcarPratoTurnoHorario_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFCARPRATOTURNO" &TFcarPratoTurno.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFCARPRATOTURNO_SEL" &TFcarPratoTurno_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFCARPRATOREFEICAO" &TFcarPratoRefeicao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFCARPRATOREFEICAO_SEL" &TFcarPratoRefeicao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"PARM_&PREFCODIGO" &prefCodigo.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"PARM_&CARDAPCODIGO" &carDapCodigo.FromString(&GridStateFilterValue.Value) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'BeforeWriteLine'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'AfterWriteLine'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub

	/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */

parm(out:&Filename, out:&ErrorMessage);

